from pathlib import Path
import tomllib


def kinds(path="spec/kinds.map"):
    out = {}
    for raw in Path(path).read_text().splitlines():
        line = raw.strip()
        if not line or line[0] in "#":
            continue
        name, backing = line.split(None, 1)
        out[name] = backing
    return out


def load_field(path="spec/typespec.toml"):
    """Load sample_stride and validate every accepted kind.

    A field may name one kind or a TOML array of kinds.  The latter represents
    an ordered union: consumers can accept either representation.
    """
    fields = tomllib.loads(Path(path).read_text())
    field = fields["sample_stride"]
    declared_kinds = field["kind"]
    if isinstance(declared_kinds, str):
        declared_kinds = [declared_kinds]
    if not isinstance(declared_kinds, list) or not all(
        isinstance(kind, str) for kind in declared_kinds
    ):
        raise SystemExit("kind must be a string or an array of strings")

    catalog = kinds()
    if any(kind not in catalog for kind in declared_kinds):
        raise SystemExit("unknown kind")
    return field
